-- Hero growth data and baby daily text corrections (owner approved 2026-11-12).
-- Review documents: Anacan-duzelis-teklifi-2026-11-12.pdf / .xlsx (audit: Anacan-hamilelik-ve-korpe-data-auditi-2026-11-12.xlsx).
-- 1) pregnancy_daily_content (active rows): fetal weight 20-40 wk from Hadlock 1991 (ln w = 0.578 + 0.332 GA - 0.00354 GA^2,
--    GA = (pregnancy_day - 1)/7), 8-19 wk from the compiled embryology table, length CRL (Robinson 1975) until 14 wk,
--    CRL table 14-20 wk, crown-heel from 20 wk; one fruit per completed week (translations for all 20 columns).
--    Also fixes day 277, stored as 3.39 g instead of ~3.5 kg.
-- 2) baby_daily_info: 23 sentences with growth figures outside WHO Child Growth Standards; only the numbers change, in az
--    and in every translation where the same numbers were found (a column with any missing number is left untouched;
--    day 246 has another day's text in 13 languages, a separate translation issue).
-- Each text update only applies if the row is unchanged since review (md5); the final checks roll everything back otherwise.
-- Both relations are already CDC enrolled and writer guarded. Applied with run-sql.py. Rollback data: backup CSVs in the
-- session scratchpad (pdc_backup.csv, bdi_full.csv).
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';

DO $$
BEGIN
  IF (SELECT count(*) FROM _anacan_gcp_migration.guarded_relations WHERE schema_name = 'public'
       AND table_name IN ('pregnancy_daily_content', 'baby_daily_info')) <> 2 THEN
    RAISE EXCEPTION 'HERO_DATA_FIX_GUARD_MISSING';
  END IF;
END $$;

UPDATE public.pregnancy_daily_content SET baby_size_cm = 0.01, baby_weight_gram = 0.01, updated_at = now() WHERE id = '3ebbef70-38c5-48c1-9efc-c1f2707c71d4' AND pregnancy_day = 26 AND is_active;
